#!/usr/bin/env sh
# Generated by nucleus-vm-setup. Dispatches to the appropriate hypervisor
# (Tart, UTM, or libvirt/virt-viewer) based on $HOST_KIND
# (substituted at VM creation time).
# Other placeholders (VM_NAME, VM_DIR) are similarly substituted.

set -eu

VM_DIR="__VM_DIR__"
HOST_KIND="__HOST_KIND__"
case "$HOST_KIND" in
  darwin-tart)
    exec tart run "__VM_NAME__"
    ;;
  darwin-utm)
    if command -v utmctl >/dev/null 2>&1; then
      utmctl start "__VM_DISPLAY__"
    else
      open "$VM_DIR/__VM_NAME__.utm"
    fi
    ;;
  nixos-libvirt)
    if ! virsh start "__VM_NAME__" >/dev/null; then
      printf 'vm-setup: virsh start failed (or VM already running): %s\n' "__VM_NAME__" >&2
    fi
    if command -v virt-viewer >/dev/null 2>&1; then
      exec virt-viewer --connect qemu:///system "__VM_NAME__"
    fi
    printf 'vm-setup: VM started: %s\n' "__VM_NAME__"
    printf 'vm-setup: install virt-viewer to open a console automatically\n'
    ;;
  *)
    printf 'vm-setup: unknown host kind: __HOST_KIND__\n' >&2
    exit 1
    ;;
esac
